const FATWA_KEYWORDS=["حكم","حلال","حرام","يجوز","لا يجوز","فتوى","مذهب","الراجح","القول الصحيح","مكروه","واجب أم","فرض أم","طلاق","ميراث","زكاة مالي","هل علي","كفارة"];const TAFSIR_DEEP_KEYWORDS=["لماذا قدّم","الإعراب","الفرق اللغوي","دلالة الحرف","القراءات","وجه الإعجاز","البلاغة في"];function classifyQuestion(text){const t=text.trim();for(const kw of FATWA_KEYWORDS){if(t.includes(kw)){return{type:"fatwa",allow:false,reason:"حكم شرعي مستنبط",message:redirectMessage("fatwa")}}}for(const kw of TAFSIR_DEEP_KEYWORDS){if(t.includes(kw)){return{type:"tafsir_deep",allow:true,reason:"تفسير لغوي تخصصي",message:null}}}return{type:"tadabbur",allow:true,reason:"تدبر وهداية",message:null}}function redirectMessage(type){const messages={fatwa:`هذا السؤال يتعلق بحكم شرعي مستنبط، وهو من اختصاص أهل العلم. \n\nأنا هنا للمساعدة في **تدبّر** الآيات والتأمل في معانيها العامة وهداياتها، أما الأحكام الفقهية والفتاوى فالأولى الرجوع فيها إلى:\n• موقع الإسلام سؤال وجواب (islamqa.info)\n• دار الإفتاء في بلدك\n• عالم ثقة تثق في علمه\n\nهل أساعدك في تدبّر آية أو فهم معناها الإجمالي بدلاً من ذلك؟`};return messages[type]||messages.fatwa}function installAIGuard(){if(typeof window.sendAIMessage!=="function"){setTimeout(installAIGuard,200);return}const _originalSend=window.sendAIMessage;window.sendAIMessage=async function(userMsg){if(!userMsg||!userMsg.trim())return;const verdict=classifyQuestion(userMsg);if(!verdict.allow){if(typeof appendMsg==="function"){appendMsg("user",userMsg);appendMsg("bot",verdict.message)}const input=document.getElementById("chat-input");if(input)input.value="";logGuardEvent(userMsg,verdict);return}return _originalSend.call(this,userMsg)};console.log("[AIGuard] ✅ طبقة الضبط الشرعي مفعّلة")}function logGuardEvent(question,verdict){try{const log=JSON.parse(localStorage.getItem("zad_ai_guard_log")||"[]");log.unshift({q:question.slice(0,100),type:verdict.type,ts:Date.now()});localStorage.setItem("zad_ai_guard_log",JSON.stringify(log.slice(0,50)))}catch(e){}}function injectReportButton(){if(!document.getElementById("chat-wrap"))return;const observer=new MutationObserver(mutations=>{mutations.forEach(m=>{m.addedNodes.forEach(node=>{if(node.nodeType===1&&node.classList?.contains("msg")&&node.classList?.contains("bot")){if(node.querySelector(".typing")||node.querySelector(".ai-report-btn"))return;addReportBtn(node)}})})});observer.observe(document.getElementById("chat-wrap"),{childList:true})}function addReportBtn(msgNode){const btn=document.createElement("button");btn.className="ai-report-btn";btn.innerHTML="⚐ الإبلاغ عن خطأ";btn.style.cssText=`\n    background: none; border: none; color: var(--muted, #888);\n    font-size: 11px; cursor: pointer; margin-top: 4px;\n    padding: 2px 8px; opacity: 0.6; font-family: inherit;\n  `;btn.onclick=()=>{const text=msgNode.querySelector(".msg-bubble")?.textContent||"";reportAIAnswer(text);btn.innerHTML="✓ شكراً للإبلاغ";btn.disabled=true};msgNode.appendChild(btn)}function reportAIAnswer(answerText){try{const reports=JSON.parse(localStorage.getItem("zad_ai_reports")||"[]");reports.unshift({answer:answerText.slice(0,200),ts:Date.now()});localStorage.setItem("zad_ai_reports",JSON.stringify(reports.slice(0,30)))}catch(e){}if(typeof showToast==="function"){showToast("✓ شكراً — سيساعدنا بلاغك في تحسين المساعد")}}window.reportAIAnswer=reportAIAnswer;const GUARD_TEST_CASES=[{q:"ما المعنى الإجمالي لسورة الفجر؟",expect:"tadabbur"},{q:"كيف أتأثر بآية وليالٍ عشر؟",expect:"tadabbur"},{q:"ما الهداية من قصة إبراهيم؟",expect:"tadabbur"},{q:"ماذا تعني آية واذكروا الله؟",expect:"tadabbur"},{q:"ما حكم صيام يوم عرفة لمن عليه قضاء؟",expect:"fatwa"},{q:"هل يجوز الجمع بين الأضحية والعقيقة؟",expect:"fatwa"},{q:"ما الراجح في حكم الادخار من الأضحية؟",expect:"fatwa"},{q:"كم كفارة من حلق رأسه في الإحرام؟",expect:"fatwa"}];function runGuardTests(){console.log("═══ اختبار الضبط الشرعي ═══");let pass=0;GUARD_TEST_CASES.forEach((tc,i)=>{const result=classifyQuestion(tc.q);const ok=result.type===tc.expect;if(ok)pass++;console.log(`${ok?"✅":"❌"} [${i+1}] "${tc.q.slice(0,40)}..." → ${result.type} (متوقع: ${tc.expect})`)});console.log(`النتيجة: ${pass}/${GUARD_TEST_CASES.length}`);return pass===GUARD_TEST_CASES.length}window.runGuardTests=runGuardTests;window.classifyQuestion=classifyQuestion;document.addEventListener("DOMContentLoaded",()=>{if(document.getElementById("chat-input")){installAIGuard();injectReportButton()}});